// TypeScript Version: 4.1

/**
* Immutably sets a value at a path in a document using structural sharing.
*
* @param document - source document
* @param tokens - array of reference tokens
* @param value - the value to set
* @throws tokens must not contain unsafe tokens
* @throws intermediate path segments must reference objects or arrays
* @returns new document with the value set at the specified path
*
* @example
* var doc = {
*     'a': {
*         'b': {
*             'c': 1
*         }
*     }
* };
* var out = set( doc, [ 'a', 'b', 'c' ], 99 );
* // returns { 'a': { 'b': { 'c': 99 } } }
*
* var bool = ( doc.a.b === out.a.b );
* // returns false
*
* bool = ( doc === out );
* // returns false
*/
declare function set( document: Array<any> | Record<string, any>, tokens: Array<string>, value: any ): any;


// EXPORTS //

export = set;
